    <style>
        :root { --ink:#17201d; --muted:#68736f; --line:#e5e9e6; --soft:#f7f9f6; --yellow:#d8ff27; --red:#b42318; } * { box-sizing:border-box; } body { margin:0; color:var(--ink); background:radial-gradient(circle at 90% 0,#e9f7c8 0,transparent 28%),#f4f7f3; font-family:Inter,system-ui,sans-serif; } a { color:inherit; text-decoration:none; } button,input,textarea { font:inherit; } .topbar { height:68px; display:flex; align-items:center; justify-content:space-between; padding:0 34px; border-bottom:1px solid var(--line); background:#fffffff2; } .brand { display:flex; align-items:center; gap:10px; color:var(--muted); font-size:14px; } .brand img { width:29px; height:29px; border-radius:50%; object-fit:cover; } .brand strong { color:var(--ink); } main { max-width:1560px; margin:auto; padding:42px 34px 70px; } .page-head { display:flex; align-items:end; justify-content:space-between; gap:20px; margin-bottom:25px; } h1 { margin:0; font-size:clamp(28px,3vw,36px); letter-spacing:-.06em; } .intro { margin:7px 0 0; color:var(--muted); font-size:14px; } .button { padding:11px 15px; border:1px solid var(--line); border-radius:9px; background:#fff; font-size:12px; font-weight:800; cursor:pointer; } .primary { color:#fff; border-color:var(--ink); background:var(--ink); } .notice,.errors { margin-bottom:18px; padding:12px 15px; border-radius:9px; font-size:13px; } .notice { color:#166534; background:#ecfdf5; } .errors { color:var(--red); background:#fff1f1; } .errors ul { margin:0; padding-left:18px; } .add-panel { display:none; margin-bottom:20px; padding:22px; border:1px solid var(--line); border-radius:16px; background:#fff; } .add-panel.open { display:block; } .add-panel h2 { margin:0 0 16px; font-size:17px; } .form-grid { display:grid; grid-template-columns:repeat(3,1fr); gap:14px; } label { display:grid; gap:7px; font-size:11px; font-weight:800; } input,textarea { width:100%; padding:10px; border:1px solid #dfe7d9; border-radius:8px; background:#fff; font-size:13px; } .full { grid-column:1/-1; } .form-actions { display:flex; justify-content:end; margin-top:16px; } .panel { overflow:hidden; border:1px solid var(--line); border-radius:16px; background:#fff; } .panel-head { display:flex; justify-content:space-between; padding:18px 22px; border-bottom:1px solid var(--line); } .count { color:var(--muted); font-size:12px; } .grid { display:grid; grid-template-columns:repeat(3,1fr); gap:18px; padding:22px; background:#f8faf7; } .card { overflow:hidden; border:1px solid var(--line); border-radius:14px; background:#fff; } .card img { display:block; width:100%; height:210px; object-fit:cover; } .info { padding:15px; } .info strong { display:block; margin-bottom:6px; font-size:14px; } .info small { display:block; min-height:32px; color:var(--muted); line-height:1.5; } .actions { display:flex; gap:8px; margin-top:14px; } .actions button { padding:8px 11px; border:1px solid var(--line); border-radius:7px; background:#fff; font-size:11px; font-weight:800; cursor:pointer; } .actions .delete { color:var(--red); border-color:#ffc8c8; background:#fff5f5; } .edit { display:none; gap:8px; margin-top:13px; } .edit.open { display:grid; } .empty { grid-column:1/-1; padding:50px; color:var(--muted); text-align:center; } @media(max-width:900px){.page-head{align-items:flex-start;flex-direction:column}.form-grid,.grid{grid-template-columns:repeat(2,1fr)}} @media(max-width:560px){main{padding:25px 14px}.form-grid,.grid{grid-template-columns:1fr}.full{grid-column:auto}}
    </style>
</head>
