    <section class="add-panel" id="add-panel"><h2>Tambah Foto Fasilitas</h2><form method="POST" action="{{ route('admin.foto-fasilitas.store') }}" enctype="multipart/form-data">@csrf<div class="form-grid"><label>Nama Fasilitas<input name="nama_fasilitas" value="{{ old('nama_fasilitas') }}" placeholder="Contoh: Kamar Tidur" required></label><label class="full">Keterangan<textarea name="keterangan" rows="3" maxlength="2000" placeholder="Jelaskan fasilitas..."></textarea></label><label class="full">File Foto<input type="file" name="file[]" multiple accept=".jpg,.jpeg,.png,.webp" required><small>JPG/PNG/WEBP, maksimal 50 MB per file.</small></label></div><div class="form-actions"><button class="button primary" type="submit">Simpan Foto</button></div></form></section>
    <section class="panel"><div class="panel-head"><strong>Daftar Foto Fasilitas</strong><span class="count">{{ $fotoFasilitas->count() }} foto</span></div><div class="grid">@forelse ($fotoFasilitas as $foto)<article class="card"><img src="{{ asset('storage/'.$foto->file_path) }}" alt="{{ $foto->nama_fasilitas }}"><div class="info"><strong>{{ $foto->nama_fasilitas }}</strong><small>{{ $foto->keterangan ?: 'Tidak ada keterangan.' }}</small><div class="actions"><button type="button" data-edit="{{ $foto->id }}">Edit</button><form method="POST" action="{{ route('admin.foto-fasilitas.destroy', $foto) }}" onsubmit="return confirm('Hapus foto fasilitas ini?')">@csrf @method('DELETE')<button class="delete" type="submit">Hapus</button></form></div><form class="edit" id="edit-{{ $foto->id }}" method="POST" action="{{ route('admin.foto-fasilitas.update', $foto) }}" enctype="multipart/form-data">@csrf @method('PATCH')<input name="nama_fasilitas" value="{{ $foto->nama_fasilitas }}" required><textarea name="keterangan" rows="2">{{ $foto->keterangan }}</textarea><input type="file" name="file" accept=".jpg,.jpeg,.png,.webp"><label><span><input type="checkbox" name="terlihat" value="1" @checked($foto->terlihat)> Tampilkan ke publik</span></label><button class="button primary" type="submit">Simpan</button></form></div></article>@empty <div class="empty">Belum ada foto fasilitas.</div>@endforelse</div></section>
</main>
<script>document.querySelector('#add-button').addEventListener('click',()=>document.querySelector('#add-panel').classList.toggle('open'));document.querySelectorAll('[data-edit]').forEach(button=>button.addEventListener('click',()=>document.querySelector('#edit-'+button.dataset.edit).classList.toggle('open')));</script>
